(*余云安-森峰需求：支撑气缸根据零件避让下落，具备夹持中的功能，但是运行过程中不动作，不执行避让*)
R_CentringCylUp1(CLK :=(g_bCentringCyl2Up1 OR bCentringCylUp1));      (*支撑气缸1上升*)
R_CentringCylDown1(CLK :=(g_bCentringCyl2Down1 OR bCentringCylDown1));  (*支撑气缸1下降*)

(*------------------------------命令输出部分---------------------------*)
(*1、命令输出有到位信号，先等到位信号，在使用延时时间，没到位信号，只使用延时时间*)
(*2、学BC，也不使用界面反馈信号灯了，只管输出*)
(*3 是否加入滤波，对硬件的输入信号，进行滤波*)
IF R_CentringCylUp1.Q THEN
  IF g_boCentringCyl2Up1 AND NOT g_boCentringCyl2Down1 THEN
    DelayTon1(IN :=FALSE);
    M.ENABLE[269] := 0; 
    g_bExecuteFinishedM269 := FALSE;
	g_bFinishedM269_1 := FALSE;
      g_boCentringCyl2Up_Done1 := TRUE;  
      g_boCentringCyl2Down_Done1 := FALSE;
  ELSE
    IF g_bUseSup2Centring1 THEN(*使用了这个气缸*)
      g_noCentringCyl2Switch1 := 10;
        (*重置输出完成信号*)
      g_boCentringCyl2Up_Done1 := FALSE;  
      g_boCentringCyl2Down_Done1 := FALSE;
    ELSE(*未使用这个气缸，则直接给完成信号*)
      g_noCentringCyl2Switch1 := 10;
      M.ENABLE[269] := 0; 
      g_bExecuteFinishedM269 := FALSE;
	  g_bFinishedM269_1 := FALSE;
      g_boCentringCyl2Up_Done1 := TRUE;  
      g_boCentringCyl2Down_Done1 := FALSE;
    END_IF;
  END_IF;

  DelayTon1(IN :=FALSE);
  bCentringCylUp1 := FALSE;  
  g_bCentringCyl2Up1 := FALSE;
  DelayTon_Down1(IN := FALSE);
  g_bCenterCyl1DownNoSignalAlarm := FALSE;

END_IF; 

IF R_CentringCylDown1.Q THEN
  IF NOT g_boCentringCyl2Up1 AND g_boCentringCyl2Down1 THEN
    DelayTon1(IN :=FALSE);
    M.ENABLE[269] := 0;
    g_bExecuteFinishedM269 := FALSE;
	g_bFinishedM269_1 := FALSE;
      g_boCentringCyl2Up_Done1 := FALSE;  
      g_boCentringCyl2Down_Done1 := TRUE; 
  ELSE
    IF g_bUseSup2Centring1 THEN(*使用了这个气缸*)
      g_noCentringCyl2Switch1 := 50;
        (*重置输出完成信号*)
      g_boCentringCyl2Up_Done1 := FALSE;  
      g_boCentringCyl2Down_Done1 := FALSE;  
    ELSE
      g_noCentringCyl2Switch1 := 0;
      M.ENABLE[269] := 0;
      g_bExecuteFinishedM269 := FALSE;
	  g_bFinishedM269_1 := FALSE;
      g_boCentringCyl2Up_Done1 := FALSE;  
      g_boCentringCyl2Down_Done1 := TRUE;  
    END_IF;
  END_IF;
  DelayTon1(IN :=FALSE);
  bCentringCylDown1 := FALSE;  
  g_bCentringCyl2Down1 := FALSE;
END_IF; 

CASE g_noCentringCyl2Switch1 OF
  0:
   g_noCentringCyl2Switch1 := 0;
  10:(*上升命令输出*)
    g_boCentringCyl2Up1 := TRUE;
    g_boCentringCyl2Down1 := FALSE;
    g_bCenterCyl1DownNoSignalAlarm := FALSE;
    DelayTon_Down1(IN := FALSE);
    DelayTon_Up1(IN := FALSE);
    fDelayTime1 := g_fCentringCyl2Up_DelayTime1;
    IF g_bCentringCyl2Up_UseINPOS1 THEN(*使用到位信号*)
      g_noCentringCyl2Switch1 := 20;
    ELSE(*使用延时信号*)
      g_noCentringCyl2Switch1 := 30;
    END_IF;
  20:(*等待到位信号*)
    IF g_bCentringCyl2Up_INPOS1 THEN
      g_boCentringCyl2Up_Done1 := TRUE;
      g_nCentringCyl2CMD1 := 1;
      g_bCentringCyl2State1 := TRUE;
      g_noCentringCyl2Switch1 := 0;
      M.ENABLE[269] := 0;
      g_bExecuteFinishedM269 := FALSE;
	  g_bFinishedM269_1 := FALSE;
      bCyl1UpState := TRUE;
      DelayTon_Up1(IN := FALSE);
      bCenterCyl1UpNoSignalAlarm := FALSE;
    ELSE
      IF NOT bCyl1UpState THEN
        DelayTon_Up1(IN := TRUE,PT := LREAL_TO_TIME(g_fCentringCyl2Up_DelayTime1/1000.0));
        IF DelayTon_Up1.Q THEN
          DelayTon_Up1(IN := FALSE);
          bCenterCyl1UpNoSignalAlarm := TRUE;
        END_IF;
      END_IF;
    END_IF;
  30:(*延时并输出完成信号*)
    DelayTon1(IN :=TRUE,PT := LREAL_TO_TIME(fDelayTime1/1000.0));
    IF DelayTon1.Q THEN
      g_boCentringCyl2Up_Done1 := TRUE;
      g_nCentringCyl2CMD1 := 1;
      g_bCentringCyl2State1 := TRUE;
      DelayTon1(IN :=FALSE);
      g_noCentringCyl2Switch1 := 0;
      M.ENABLE[269] := 0;
      g_bExecuteFinishedM269 := FALSE;
	  g_bFinishedM269_1 := FALSE;
      bCyl1UpState := TRUE;
    END_IF;

  50:(*下降命令输出*)
    g_boCentringCyl2Up1 := FALSE;
    g_boCentringCyl2Down1 := TRUE;
    DelayTon_Up1(IN := FALSE);
    bCenterCyl1UpNoSignalAlarm := FALSE;
    fDelayTime1 := g_fCentringCyl2Down_DelayTime1;
    IF g_bCentringCyl2Down_UseINPOS1 THEN(*使用到位信号*)
      g_noCentringCyl2Switch1 := 60;
    ELSE(*使用延时信号*)
      g_noCentringCyl2Switch1 := 70;
    END_IF;
  60: (*等待到位信号*)
    IF g_bCentringCyl2Down_INPOS1 THEN
       g_boCentringCyl2Down_Done1 := TRUE;
      g_nCentringCyl2CMD1 := -1;
      g_bCentringCyl2State1 := FALSE;
      g_noCentringCyl2Switch1 := 0;
      M.ENABLE[269] := 0;
      g_bExecuteFinishedM269 := FALSE;
	  g_bFinishedM269_1 := FALSE;
      DelayTon_Down1(IN := FALSE);
      g_bCenterCyl1DownNoSignalAlarm := FALSE;
      bCyl1UpState := FALSE;
    ELSE
      IF bCyl1UpState THEN
        DelayTon_Down1(IN := TRUE,PT := LREAL_TO_TIME(g_fCentringCyl2Down_DelayTime1/1000.0));
        IF DelayTon_Down1.Q THEN
          DelayTon_Down1(IN := FALSE);
          g_bCenterCyl1DownNoSignalAlarm := TRUE;
        END_IF;
      END_IF;
    END_IF;
  70:(*延时并输出完成信号*)
    DelayTon1(IN :=TRUE,PT := LREAL_TO_TIME(fDelayTime1/1000.0));
    IF DelayTon1.Q THEN
      g_boCentringCyl2Down_Done1 := TRUE;
      g_nCentringCyl2CMD1 := -1;
      g_bCentringCyl2State1 := FALSE;
      DelayTon1(IN :=FALSE);
      g_noCentringCyl2Switch1 := 0;
      M.ENABLE[269] := 0;
      g_bExecuteFinishedM269 := FALSE;
	  g_bFinishedM269_1 := FALSE;
      bCyl1UpState := FALSE;
    END_IF;
END_CASE;

(*新加的气缸状态切换,气缸到位超时报警和目前默认到位时间用的一个时间*)
CentringCyl1State(
  bUseUpSignal := g_bCentringCyl2Up_UseINPOS1,
  bUseDownSignal := g_bCentringCyl2Down_UseINPOS1,
  boCylUp := g_boCentringCyl2Up1,
  boCylDown := g_boCentringCyl2Down1,
  bUpInplace := g_bCentringCyl2Up_INPOS1,
  bDownInplace := g_bCentringCyl2Down_INPOS1,
  bUpInplaceNoFilter := bCyl1UpSignalNoFilter,
  bDownInplaceNoFilter := bCyl1DownSignalNoFilter,
  dClylinderUpDelayTime := LREAL_TO_DINT(g_fCentringCyl2Up_DelayTime1),
  dClylinderDownDelayTime := LREAL_TO_DINT(g_fCentringCyl2Down_DelayTime1),
  dClylinderUpOverDelayTime := LREAL_TO_DINT(g_fCentringCyl2Up_DelayTime1),
  dClylinderDownOverDelayTime := LREAL_TO_DINT(g_fCentringCyl2Down_DelayTime1),
  bArrayConfigOutputUp := ArrayConfigOutputNumber[130],
  bArrayConfigOutputDown := ArrayConfigOutputNumber[133],
  bCylState  => bCyl1UpState,
  bCylStateToHMI => g_bCentringCyl2State1,
  bCylUpNoSignalAlarm => bCenterCyl1UpNoSignalAlarm,
  bCylDownNoSignalAlarm => g_bCenterCyl1DownNoSignalAlarm,
  bArrayConfigOutputUp_FB => ArrayConfigOutputNumber[130],
  bArrayConfigOutputDown_FB => ArrayConfigOutputNumber[133]
);

R_CentringCylUp2(CLK :=(g_bCentringCyl2Up2 OR bCentringCylUp2));      (*支撑气缸2上升*)
