      (*重置输出完成信号*)
      g_boCentringCyl2Up_Done2 := FALSE;  
      g_boCentringCyl2Down_Done2 := FALSE;
    ELSE
      g_noCentringCyl2Switch2 := 0;
      M.ENABLE[269] := 0;
      g_bExecuteFinishedM269 := FALSE;
	  g_bFinishedM269_2 := FALSE;
      g_boCentringCyl2Up_Done2 := TRUE;  
      g_boCentringCyl2Down_Done2 := FALSE;
    END_IF;
  END_IF;
  DelayTon2(IN :=FALSE);
  bCentringCylUp2 := FALSE;  
  g_bCentringCyl2Up2 := FALSE;
  DelayTon_Down2(IN := FALSE);
  g_bCenterCyl2DownNoSignalAlarm := FALSE;
END_IF; 

IF R_CentringCylDown2.Q THEN
