    g_bExecuteFinishedM269 := FALSE;
	g_bFinishedM269_2 := FALSE;
      g_boCentringCyl2Up_Done2 := FALSE;  
      g_boCentringCyl2Down_Done2 := TRUE;
  ELSE
    IF g_bUseSup2Centring2 THEN(*使用了这个气缸*)
      g_noCentringCyl2Switch2 := 50;
      (*重置输出完成信号*)
      g_boCentringCyl2Up_Done2 := FALSE;  
      g_boCentringCyl2Down_Done2 := FALSE;  
    ELSE
      g_noCentringCyl2Switch2 := 0;
      M.ENABLE[269] := 0;
      g_bExecuteFinishedM269 := FALSE;
	  g_bFinishedM269_2 := FALSE;
      g_boCentringCyl2Up_Done2 := FALSE;  
      g_boCentringCyl2Down_Done2 := TRUE;  
    END_IF;
  END_IF;
  DelayTon2(IN :=FALSE);
  bCentringCylDown2 := FALSE;  
  g_bCentringCyl2Down2 := FALSE;

END_IF; 

