  bUseUpSignal := g_bCentringCyl2Up_UseINPOS3,
  bUseDownSignal := g_bCentringCyl2Down_UseINPOS3,
  boCylUp := g_boCentringCyl2Up3,
  boCylDown := g_boCentringCyl2Down3,
  bUpInplace := g_bCentringCyl2Up_INPOS3,
  bDownInplace := g_bCentringCyl2Down_INPOS3,
  bUpInplaceNoFilter := bCyl3UpSignalNoFilter,
  bDownInplaceNoFilter := bCyl3DownSignalNoFilter,
  dClylinderUpDelayTime := LREAL_TO_DINT(g_fCentringCyl2Up_DelayTime3),
  dClylinderDownDelayTime := LREAL_TO_DINT(g_fCentringCyl2Down_DelayTime3),
  dClylinderUpOverDelayTime := LREAL_TO_DINT(g_fCentringCyl2Up_DelayTime3),
  dClylinderDownOverDelayTime := LREAL_TO_DINT(g_fCentringCyl2Down_DelayTime3),
  bArrayConfigOutputUp := ArrayConfigOutputNumber[132],
  bArrayConfigOutputDown := ArrayConfigOutputNumber[135],
  bCylState  => bCyl3UpState,
  bCylStateToHMI => g_bCentringCyl2State3,
  bCylUpNoSignalAlarm => bCenterCyl3UpNoSignalAlarm,
  bCylDownNoSignalAlarm => g_bCenterCyl3DownNoSignalAlarm,
  bArrayConfigOutputUp_FB => ArrayConfigOutputNumber[132],
  bArrayConfigOutputDown_FB => ArrayConfigOutputNumber[135]
);



R_CentringCylUp4(CLK :=(g_bCentringCyl2Up4 OR bCentringCylUp4));      
R_CentringCylDown4(CLK :=(g_bCentringCyl2Down4 OR bCentringCylDown4));  

IF R_CentringCylUp4.Q THEN
  IF g_boCentringCyl2Up4 AND NOT g_boCentringCyl2Down4 THEN
    DelayTon4(IN :=FALSE);
    M.ENABLE[269] := 0;
    g_bExecuteFinishedM269 := FALSE;
	g_bFinishedM269_4 := FALSE;
      g_boCentringCyl2Up_Done4 := TRUE;  
      g_boCentringCyl2Down_Done4 := FALSE;
  ELSE
    IF g_bUseSup2Centring4 THEN(*使用了这个气缸*)
      g_noCentringCyl2Switch4 := 10;
        (*重置输出完成信号*)
      g_boCentringCyl2Up_Done4 := FALSE;  
      g_boCentringCyl2Down_Done4 := FALSE;
    ELSE
      g_noCentringCyl2Switch4 := 0;
      M.ENABLE[269] := 0; 
      g_bExecuteFinishedM269 := FALSE;
	  g_bFinishedM269_4 := FALSE;
      g_boCentringCyl2Up_Done4 := TRUE;  
      g_boCentringCyl2Down_Done4 := FALSE;
    END_IF;
  END_IF;
  DelayTon4(IN :=FALSE);
  bCentringCylUp4 := FALSE;  
  g_bCentringCyl2Up4 := FALSE;
  DelayTon_Down4(IN := FALSE);
  g_bCenterCyl4DownNoSignalAlarm := FALSE;
END_IF; 

IF R_CentringCylDown4.Q THEN
  IF NOT g_boCentringCyl2Up4 AND g_boCentringCyl2Down4 THEN
    DelayTon4(IN :=FALSE);
    M.ENABLE[269] := 0;
    g_bExecuteFinishedM269 := FALSE;
	g_bFinishedM269_4 := FALSE;
      g_boCentringCyl2Up_Done4 := FALSE;  
      g_boCentringCyl2Down_Done4 := TRUE; 
  ELSE
    IF g_bUseSup2Centring4 THEN(*使用了这个气缸*)
      g_noCentringCyl2Switch4 := 50;
        (*重置输出完成信号*)
      g_boCentringCyl2Up_Done4 := FALSE;  
      g_boCentringCyl2Down_Done4 := FALSE; 
    ELSE
      g_noCentringCyl2Switch4 := 0;
      M.ENABLE[269] := 0;
      g_bExecuteFinishedM269 := FALSE;
	  g_bFinishedM269_4 := FALSE;
      g_boCentringCyl2Up_Done4 := FALSE;  
      g_boCentringCyl2Down_Done4 := TRUE; 
    END_IF;
  END_IF;
  DelayTon4(IN :=FALSE);
  bCentringCylDown4 := FALSE;  
  g_bCentringCyl2Down4 := FALSE;

END_IF; 

CASE g_noCentringCyl2Switch4 OF
  0:
   g_noCentringCyl2Switch4 := 0;
  10:(*上升命令输出*)
    g_boCentringCyl2Up4 := TRUE;
    g_boCentringCyl2Down4 := FALSE;
    g_bCenterCyl4DownNoSignalAlarm := FALSE;
    DelayTon_Down4(IN := FALSE);
    DelayTon_Up4(IN := FALSE);
    fDelayTime4 := g_fCentringCyl2Up_DelayTime4;
    IF g_bCentringCyl2Up_UseINPOS4 THEN(*使用到位信号*)
      g_noCentringCyl2Switch4 := 20;
    ELSE(*使用延时信号*)
      g_noCentringCyl2Switch4 := 30;
    END_IF;
  20:(*等待到位信号*)
    IF g_bCentringCyl2Up_INPOS4 THEN
      g_boCentringCyl2Up_Done4 := TRUE;
      g_noCentringCyl2Switch4 := 0;
      M.ENABLE[269] := 0;
      g_bExecuteFinishedM269 := FALSE;
	  g_bFinishedM269_4 := FALSE;
      g_bCentringCyl2State4 := TRUE;
      bCyl4UpState := TRUE;
      DelayTon_Up4(IN := FALSE);
      bCenterCyl4UpNoSignalAlarm := FALSE;
    ELSE
      IF NOT bCyl4UpState THEN
        DelayTon_Up4(IN := TRUE,PT := LREAL_TO_TIME(g_fCentringCyl2Up_DelayTime4/1000.0));
        IF DelayTon_Up4.Q THEN
          DelayTon_Up4(IN := FALSE);
          bCenterCyl4UpNoSignalAlarm := TRUE;
        END_IF;
      END_IF;
    END_IF;
  30:(*延时并输出完成信号*)
    DelayTon4(IN :=TRUE,PT := LREAL_TO_TIME(fDelayTime4/1000.0));
    IF DelayTon4.Q THEN
      g_boCentringCyl2Up_Done4 := TRUE;
      DelayTon4(IN :=FALSE);
      g_noCentringCyl2Switch4 := 0;
      M.ENABLE[269] := 0;
      g_bExecuteFinishedM269 := FALSE;
	  g_bFinishedM269_4 := FALSE;
      g_bCentringCyl2State4 := TRUE;
      bCyl4UpState := TRUE;
    END_IF;

  50:(*下降命令输出*)
    g_boCentringCyl2Up4 := FALSE;
    g_boCentringCyl2Down4 := TRUE;
    DelayTon_Up4(IN := FALSE);
    bCenterCyl4UpNoSignalAlarm := FALSE;
    fDelayTime4 := g_fCentringCyl2Down_DelayTime4;
    IF g_bCentringCyl2Down_UseINPOS4 THEN(*使用到位信号*)
      g_noCentringCyl2Switch4 := 60;
    ELSE(*使用延时信号*)
      g_noCentringCyl2Switch4 := 70;
    END_IF;
  60: (*等待到位信号*)
    IF g_bCentringCyl2Down_INPOS4 THEN
      g_boCentringCyl2Down_Done4 := TRUE;
      g_noCentringCyl2Switch4 := 0;
      M.ENABLE[269] := 0;
      g_bExecuteFinishedM269 := FALSE;
	  g_bFinishedM269_4 := FALSE;
      g_bCentringCyl2State4 := FALSE;
      DelayTon_Down4(IN := FALSE);
      g_bCenterCyl4DownNoSignalAlarm := FALSE;
      bCyl4UpState := FALSE;
    ELSE
      IF bCyl4UpState THEN
        DelayTon_Down4(IN := TRUE,PT :=LREAL_TO_TIME(g_fCentringCyl2Down_DelayTime4/1000.0));
        IF DelayTon_Down4.Q THEN
          DelayTon_Down4(IN := FALSE);
          g_bCenterCyl4DownNoSignalAlarm := TRUE;
        END_IF;
      END_IF;
    END_IF;
  70:(*延时并输出完成信号*)
    DelayTon4(IN :=TRUE,PT := LREAL_TO_TIME(fDelayTime4/1000.0));
    IF DelayTon4.Q THEN
      g_boCentringCyl2Down_Done4 := TRUE;
      DelayTon4(IN :=FALSE);
      g_noCentringCyl2Switch4 := 0;
      M.ENABLE[269] := 0;
      g_bExecuteFinishedM269 := FALSE;
	  g_bFinishedM269_4 := FALSE;
      g_bCentringCyl2State4 := FALSE;
      bCyl4UpState := FALSE;
    END_IF;
END_CASE;


(*新加的气缸状态切换,气缸到位超时报警和目前默认到位时间用的一个时间*)
CentringCyl4State(
  bUseUpSignal := g_bCentringCyl2Up_UseINPOS4,
  bUseDownSignal := g_bCentringCyl2Down_UseINPOS4,
  boCylUp := g_boCentringCyl2Up4,
  boCylDown := g_boCentringCyl2Down4,
  bUpInplace := g_bCentringCyl2Up_INPOS4,
  bDownInplace := g_bCentringCyl2Down_INPOS4,
  bUpInplaceNoFilter := bCyl4UpSignalNoFilter,
  bDownInplaceNoFilter := bCyl4DownSignalNoFilter,
  dClylinderUpDelayTime := LREAL_TO_DINT(g_fCentringCyl2Up_DelayTime4),
  dClylinderDownDelayTime := LREAL_TO_DINT(g_fCentringCyl2Down_DelayTime4),
  dClylinderUpOverDelayTime := LREAL_TO_DINT(g_fCentringCyl2Up_DelayTime4),
  dClylinderDownOverDelayTime := LREAL_TO_DINT(g_fCentringCyl2Down_DelayTime4),
  bArrayConfigOutputUp := ArrayConfigOutputNumber[188],
  bArrayConfigOutputDown := ArrayConfigOutputNumber[189],
  bCylState  => bCyl4UpState,
  bCylStateToHMI => g_bCentringCyl2State4,
  bCylUpNoSignalAlarm => bCenterCyl4UpNoSignalAlarm,
  bCylDownNoSignalAlarm => g_bCenterCyl4DownNoSignalAlarm,
  bArrayConfigOutputUp_FB => ArrayConfigOutputNumber[188],
  bArrayConfigOutputDown_FB => ArrayConfigOutputNumber[189]
);
(*对中气缸到位信号添加滤波*)
Fileter_4(LREAL_TO_TIME(FUN_MSTOS(Cyl1FilterTime)),g_bCentringCyl2Up_NONC1,g_biCentringCyl2Up_INPOS1,g_bCentringCyl2Up_INPOS1);
g_bCentringCyl2Up_INPOS1 := FUN_SingalLogic(g_bCentringCyl2Up_INPOS1,g_bCentringCyl2Up_NONC1);
Fileter_1(LREAL_TO_TIME(FUN_MSTOS(Cyl1FilterTime)),g_bCentringCyl2Down_NONC1,g_biCentringCyl2Down_INPOS1,g_bCentringCyl2Down_INPOS1);
g_bCentringCyl2Down_INPOS1 := FUN_SingalLogic(g_bCentringCyl2Down_INPOS1,g_bCentringCyl2Down_NONC1);

bCyl1UpSignalNoFilter := FUN_SingalLogic(g_biCentringCyl2Up_INPOS1,g_bCentringCyl2Up_NONC1);
bCyl1DownSignalNoFilter := FUN_SingalLogic(g_biCentringCyl2Down_INPOS1,g_bCentringCyl2Down_NONC1);

Fileter_5(LREAL_TO_TIME(FUN_MSTOS(Cyl2FilterTime)),g_bCentringCyl2Up_NONC2,g_biCentringCyl2Up_INPOS2,g_bCentringCyl2Up_INPOS2);
g_bCentringCyl2Up_INPOS2 := FUN_SingalLogic(g_bCentringCyl2Up_INPOS2,g_bCentringCyl2Up_NONC2);
Fileter_2(LREAL_TO_TIME(FUN_MSTOS(Cyl2FilterTime)),g_bCentringCyl2Down_NONC2,g_biCentringCyl2Down_INPOS2,g_bCentringCyl2Down_INPOS2);
g_bCentringCyl2Down_INPOS2 := FUN_SingalLogic(g_bCentringCyl2Down_INPOS2,g_bCentringCyl2Down_NONC2);

bCyl2UpSignalNoFilter := FUN_SingalLogic(g_biCentringCyl2Up_INPOS2,g_bCentringCyl2Up_NONC2);
bCyl2DownSignalNoFilter := FUN_SingalLogic(g_biCentringCyl2Down_INPOS2,g_bCentringCyl2Down_NONC2);

Fileter_6(LREAL_TO_TIME(FUN_MSTOS(Cyl3FilterTime)),g_bCentringCyl2Up_NONC3,g_biCentringCyl2Up_INPOS3,g_bCentringCyl2Up_INPOS3);
g_bCentringCyl2Up_INPOS3 := FUN_SingalLogic(g_bCentringCyl2Up_INPOS3,g_bCentringCyl2Up_NONC3);
Fileter_3(LREAL_TO_TIME(FUN_MSTOS(Cyl3FilterTime)),g_bCentringCyl2Down_NONC3,g_biCentringCyl2Down_INPOS3,g_bCentringCyl2Down_INPOS3);
g_bCentringCyl2Down_INPOS3 := FUN_SingalLogic(g_bCentringCyl2Down_INPOS3,g_bCentringCyl2Down_NONC3);

bCyl3UpSignalNoFilter := FUN_SingalLogic(g_biCentringCyl2Up_INPOS3,g_bCentringCyl2Up_NONC3);
bCyl3DownSignalNoFilter := FUN_SingalLogic(g_biCentringCyl2Down_INPOS3,g_bCentringCyl2Down_NONC3);

Fileter_7(LREAL_TO_TIME(FUN_MSTOS(Cyl4FilterTime)),g_bCentringCyl2Up_NONC4,g_biCentringCyl2Up_INPOS4,g_bCentringCyl2Up_INPOS4);
g_bCentringCyl2Up_INPOS4 := FUN_SingalLogic(g_bCentringCyl2Up_INPOS4,g_bCentringCyl2Up_NONC4);
Fileter_8(LREAL_TO_TIME(FUN_MSTOS(Cyl4FilterTime)),g_bCentringCyl2Down_NONC4,g_biCentringCyl2Down_INPOS4,g_bCentringCyl2Down_INPOS4);
g_bCentringCyl2Down_INPOS4 := FUN_SingalLogic(g_bCentringCyl2Down_INPOS4,g_bCentringCyl2Down_NONC4);

bCyl4UpSignalNoFilter := FUN_SingalLogic(g_biCentringCyl2Up_INPOS4,g_bCentringCyl2Up_NONC4);
bCyl4DownSignalNoFilter := FUN_SingalLogic(g_biCentringCyl2Down_INPOS4,g_bCentringCyl2Down_NONC4);

(*对中气缸上升到位信号超时报警*)
IF bCenterCyl1UpNoSignalAlarm AND ListenBoardInputConfig[405]  THEN
  g_Alarm.alarmArray[531] := 1244;
ELSE
  g_Alarm.alarmArray[531] := 0;
END_IF;
IF bCenterCyl2UpNoSignalAlarm AND ListenBoardInputConfig[406] THEN
  g_Alarm.alarmArray[532] := 1245;
ELSE
  g_Alarm.alarmArray[532] := 0;
END_IF;
IF bCenterCyl3UpNoSignalAlarm AND ListenBoardInputConfig[407] THEN
  g_Alarm.alarmArray[533] := 1246;
ELSE
  g_Alarm.alarmArray[533] := 0;
END_IF;
IF bCenterCyl4UpNoSignalAlarm AND ListenBoardInputConfig[457] THEN
